/** The bare npm export target for a row (npmFile > invariant file > solid). */
function bareNpmTarget(name: string, decl: SubpathDecl): string {
  const target =
    decl.npmFile ?? (typeof decl.file === "string" ? decl.file : decl.file.solid);
  if (!target) {
    throw new Error(`subpaths: "${name}" has no bare npm target (npmFile or solid file required)`);
  }
  return target;
}

/**
 * The derived npm `exports` map, in canonical order: bare rows in
 * declaration order, then each framework's alias group. tools/gen-exports.ts
 * writes this into package.json; tests/contract.ts regenerates and compares.
 */
export function npmExports(): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [name, decl] of Object.entries(SUBPATHS)) {
    out[name === "" ? "." : `./${name}`] = `./${bareNpmTarget(name, decl)}`;
  }
  for (const fw of POCKET_FRAMEWORKS) {
    for (const [name, decl] of Object.entries(SUBPATHS)) {
      if (!decl.aliases?.includes(fw)) continue;
      const rel = typeof decl.file === "string" ? decl.file : decl.file[fw];
      if (!rel) {
        throw new Error(`subpaths: "${name}" aliases ${fw} but has no ${fw} file`);
      }
      out[name === "" ? `./${fw}` : `./${fw}/${name}`] = `./${rel}`;
    }
  }
  return out;
}
